@@ -0,0 +1,97 @@
+import type { TabId } from "@blueprintjs/core";
+import {
+  SETTINGS_TAB_IDS,
+  isSettingsTabId,
+  resolveSettingsTabId,
+} from "./settingsTabs";
+
+/** Settings dialog route: `["grammar-nodes", nodeTypeUid, "template"]`, tab first. */
+export type SettingsPath = readonly string[];
+
+export type SettingsNavAction =
+  | { type: "select-tab"; tabId: string }
+  | { type: "navigate"; path: SettingsPath }
+  | { type: "push"; segment: string }
+  | { type: "pop" }
+  | { type: "truncate"; depth: number };
+
+export const nodeConfigSegmentIds = {
+  index: "index",
+  template: "template",
+} as const;
+
+export const rootPath = (tabId: string): SettingsPath => [tabId];
+
+export const tabIdOf = (path: SettingsPath): string => path[0] ?? "";
+
+/** Drill-down segments below the tab; 0 is the tab's own root page. */
+export const depthOf = (path: SettingsPath): number =>
+  Math.max(0, path.length - 1);
+
+export const segmentsOf = (path: SettingsPath): readonly string[] =>
+  path.slice(1);
+
+export const isSamePath = (a: SettingsPath, b: SettingsPath): boolean =>
+  a.length === b.length && a.every((segment, index) => segment === b[index]);
+
+export const settingsNavReducer = (
+  state: SettingsPath,
+  action: SettingsNavAction,
+): SettingsPath => {
+  switch (action.type) {
+    case "select-tab":
+      return action.tabId === tabIdOf(state) && state.length === 1
+        ? state
+        : rootPath(action.tabId);
+    // Search jumps several segments at once; an empty path is ignored.
+    case "navigate":
+      return action.path.length === 0 || isSamePath(action.path, state)
+        ? state
+        : [...action.path];
+    case "push":
+      return [...state, action.segment];
+    case "pop":
+      return state.length <= 1 ? state : state.slice(0, -1);
+    case "truncate": {
+      const length = Math.max(1, action.depth + 1);
+      return length >= state.length ? state : state.slice(0, length);
+    }
+  }
+};
+
+/** An id that is not a tab is a node type uid from the old per-node tabs; it opens
+ *  inside Grammar > Nodes. */
+export const resolveInitialSettingsPath = (
+  selectedTabId?: TabId,
+): SettingsPath => {
+  const tabId = resolveSettingsTabId(selectedTabId);
+  return isSettingsTabId(tabId)
+    ? rootPath(tabId)
+    : [SETTINGS_TAB_IDS.grammarNodes, String(tabId)];
+};
+
+export type SettingsCrumb = {
+  label: string;
+  depth: number;
+  isCurrent: boolean;
+};
+
+export const buildBreadcrumbTrail = ({
+  path,
+  rootLabel,
+  resolveLabel,
+}: {
+  path: SettingsPath;
+  rootLabel: string;
+  resolveLabel: (segment: string, segmentIndex: number) => string;
+}): SettingsCrumb[] => {
+  const segments = segmentsOf(path);
+  return [
+    { label: rootLabel, depth: 0, isCurrent: segments.length === 0 },
+    ...segments.map((segment, index) => ({
+      label: resolveLabel(segment, index),
+      depth: index + 1,
+      isCurrent: index === segments.length - 1,
+    })),
+  ];
+};
diff --git a/apps/roam/src/components/settings/utils/settingsSearch.ts b/apps/roam/src/components/settings/utils/settingsSearch.ts
new file mode 100644
index 00000000..c5a98f42
--- /dev/null
+++ b/apps/roam/src/components/settings/utils/settingsSearch.ts
@@ -0,0 +1,112 @@
+import type { SearchableEntry } from "./settingsCatalog";
+
+export const SETTINGS_SEARCH_RESULT_LIMIT = 8;
+
+/** Lower is better, so an exact label is never buried under a description that
+ *  happens to mention the same word. */
+const MatchTier = {
+  exactLabel: 0,
+  labelPrefix: 1,
+  labelSubstring: 2,
+  breadcrumb: 3,
+  keyword: 4,
+  description: 5,
+} as const;
+
+type Tier = (typeof MatchTier)[keyof typeof MatchTier];
+
+const normalize = (value: string): string =>
+  value.toLowerCase().replace(/\s+/g, " ").trim();
+
+/** Per-node entries repeat their breadcrumb and description for every node type, so
+ *  matching either would bury the one relevant page under a row per type. */
+const isRepeated = (entry: SearchableEntry): boolean =>
+  entry.nodeTypeUid !== undefined;
+
+const searchableDescription = (entry: SearchableEntry): string =>
+  entry.kind === "setting" && !isRepeated(entry)
+    ? (entry.description ?? "")
+    : "";
+
+const haystackOf = (entry: SearchableEntry): string =>
+  normalize(
+    [
+      entry.label,
+      isRepeated(entry) ? "" : entry.breadcrumb,
+      ...entry.keywords,
+      searchableDescription(entry),
+    ].join(" "),
+  );
+
+const tierFor = (entry: SearchableEntry, query: string): Tier | null => {
+  const label = normalize(entry.label);
+  if (label === query) return MatchTier.exactLabel;
+  if (label.startsWith(query)) return MatchTier.labelPrefix;
+  if (label.includes(query)) return MatchTier.labelSubstring;
+  if (!isRepeated(entry) && normalize(entry.breadcrumb).includes(query))
+    return MatchTier.breadcrumb;
+  if (entry.keywords.some((keyword) => normalize(keyword).includes(query)))
+    return MatchTier.keyword;
+  const description = normalize(searchableDescription(entry));
+  if (description && description.includes(query)) return MatchTier.description;
+  return null;
+};
+
+/** Multi-word queries match when every word appears somewhere, but the tier still comes
+ *  from the whole query, so single-word precision is not diluted. */
+const matches = (
+  entry: SearchableEntry,
+  query: string,
+): { tier: Tier } | null => {
+  const whole = tierFor(entry, query);
+  if (whole !== null) return { tier: whole };
+
+  const words = query.split(" ").filter(Boolean);
+  if (words.length < 2) return null;
+  const haystack = haystackOf(entry);
+  return words.every((word) => haystack.includes(word))
+    ? { tier: MatchTier.description }
+    : null;
+};
+
+const isLabelMatch = (tier: Tier): boolean => tier <= MatchTier.labelSubstring;
+
+/** Per-node rows trail one-off rows among label matches, so a row per node type cannot
+ *  fill the limit ahead of a page or a one-off setting with the same word. */
+const isPerNodeRow = (entry: SearchableEntry): boolean =>
+  entry.kind === "setting" && isRepeated(entry);
+
+/** Settings before pages at the same tier; then alphabetical, for a stable list. */
+const compare = (
+  a: { entry: SearchableEntry; tier: Tier },
+  b: { entry: SearchableEntry; tier: Tier },
+): number => {
+  if (isLabelMatch(a.tier) !== isLabelMatch(b.tier))
+    return isLabelMatch(a.tier) ? -1 : 1;
+  if (isPerNodeRow(a.entry) !== isPerNodeRow(b.entry))
+    return isPerNodeRow(a.entry) ? 1 : -1;
+  if (a.tier !== b.tier) return a.tier - b.tier;
+  if (a.entry.kind !== b.entry.kind) return a.entry.kind === "setting" ? -1 : 1;
+  return a.entry.label.localeCompare(b.entry.label);
+};
+
+export const rankSettings = ({
+  entries,
+  query,
+  limit = SETTINGS_SEARCH_RESULT_LIMIT,
+}: {
+  entries: readonly SearchableEntry[];
+  query: string;
+  limit?: number;
+}): SearchableEntry[] => {
+  const normalized = normalize(query);
+  if (normalized === "") return [];
+  return entries
+    .flatMap((entry) => {
+      const match = matches(entry, normalized);
+      return match ? [{ entry, tier: match.tier }] : [];
+    })
+    .sort(compare)
+    .slice(0, limit)
+    .map(({ entry }) => entry);
+};
